246	fn complete_option(
247	    arg: &clap_lex::ParsedArg<'_>,
248	    cmd: &clap::Command,
249	    current_dir: Option<&std::path::Path>,
250	) -> Vec<CompletionCandidate> {
251	    debug!("complete_option: arg={arg:?}, current_dir={current_dir:?}");
252	    let mut completions = Vec::<CompletionCandidate>::new();
253	    if arg.is_empty() {
254	        completions.extend(longs_and_visible_aliases(cmd));
255	        completions.extend(hidden_longs_aliases(cmd));
256	
257	        let dash_or_arg = if arg.is_empty() {
258	            "-".into()
259	        } else {
260	            arg.to_value_os().to_string_lossy()
261	        };
262	        completions.extend(
263	            shorts_and_visible_aliases(cmd)
264	                .into_iter()
265	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
266	        );
267	    } else if arg.is_stdio() {
268	        // HACK: Assuming knowledge of is_stdio
269	        let dash_or_arg = if arg.is_empty() {
270	            "-".into()
271	        } else {
272	            arg.to_value_os().to_string_lossy()
273	        };
274	        completions.extend(
275	            shorts_and_visible_aliases(cmd)
276	                .into_iter()
277	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
278	        );
279	
280	        completions.extend(longs_and_visible_aliases(cmd));
281	        completions.extend(hidden_longs_aliases(cmd));
282	    } else if arg.is_escape() {
283	        // HACK: Assuming knowledge of is_escape
284	        completions.extend(longs_and_visible_aliases(cmd));
285	        completions.extend(hidden_longs_aliases(cmd));
286	    } else if let Some((flag, value)) = arg.to_long() {
287	        if let Ok(flag) = flag {
288	            if let Some(value) = value {
289	                if let Some(arg) = cmd.get_arguments().find(|a| a.get_long() == Some(flag)) {
290	                    completions.extend(
291	                        complete_arg_value(value.to_str().ok_or(value), arg, current_dir, 0)
292	                            .into_iter()
293	                            .map(|comp| comp.add_prefix(format!("--{flag}="))),
294	                    );
295	                }
296	            } else {
297	                completions.extend(
298	                    longs_and_visible_aliases(cmd)
299	                        .into_iter()
300	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
301	                );
302	                completions.extend(
303	                    hidden_longs_aliases(cmd)
304	                        .into_iter()
305	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
306	                );
307	            }
308	        }
309	    } else if let Some(short) = arg.to_short() {
310	        if !short.is_negative_number() {
311	            // Find the first takes_values option.
312	            let (leading_flags, takes_value_opt, mut short) = parse_shortflags(cmd, short);
313	
314	            // Clone `short` to `peek_short` to peek whether the next flag is a `=`.
315	            if let Some(opt) = takes_value_opt {
316	                let mut peek_short = short.clone();
317	                let has_equal = if let Some(Ok('=')) = peek_short.next_flag() {
318	                    short.next_flag();
319	                    true
320	                } else {
321	                    false
322	                };
323	
324	                let value = short.next_value_os().unwrap_or(OsStr::new(""));
325	                completions.extend(
326	                    complete_arg_value(value.to_str().ok_or(value), opt, current_dir, 0)
327	                        .into_iter()
328	                        .map(|comp| {
329	                            let sep = if has_equal { "=" } else { "" };
330	                            comp.add_prefix(format!("-{leading_flags}{sep}"))
331	                        }),
332	                );
333	            } else {
334	                completions.extend(
335	                    shorts_and_visible_aliases(cmd)
336	                        .into_iter()
337	                        .map(|comp| comp.add_prefix(format!("-{leading_flags}"))),
338	                );
339	            }
340	        }
341	    }
342	    debug!("complete_option: completions={completions:?}");
343	    completions
344	}
