346	fn complete_arg_value(
347	    value: Result<&str, &OsStr>,
348	    arg: &clap::Arg,
349	    current_dir: Option<&std::path::Path>,
350	    arg_index: usize,
351	) -> Vec<CompletionCandidate> {
352	    let mut values = Vec::new();
353	    debug!("complete_arg_value: arg={arg:?}, value={value:?}, arg_index={arg_index:?}");
354	
355	    let (prefix, value) =
356	        rsplit_delimiter(value, arg.get_value_delimiter()).unwrap_or((None, value));
357	
358	    let value_os = match value {
359	        Ok(value) => OsStr::new(value),
360	        Err(value_os) => value_os,
361	    };
362	
363	    if let Some(completer) = arg.get::<ArgValueCompleter>() {
364	        values.extend(completer.complete_at(arg_index, value_os));
365	    } else if let Some(completer) = arg.get::<ArgValueCandidates>() {
366	        values.extend(complete_value_candidates(
367	            value_os,
368	            completer.value_candidates(),
369	        ));
370	    } else if let Some(possible_values) = possible_values(arg) {
371	        if let Ok(value) = value {
372	            values.extend(complete_candidates_str(
373	                value,
374	                possible_value_candidates(possible_values),
375	            ));
376	        }
377	    } else {
378	        match arg.get_value_hint() {
379	            clap::ValueHint::Unknown | clap::ValueHint::Other => {
380	                // Should not complete
381	            }
382	            clap::ValueHint::AnyPath => {
383	                values.extend(complete_path(value_os, current_dir, &|_| true));
384	            }
385	            clap::ValueHint::FilePath => {
386	                values.extend(complete_path(value_os, current_dir, &|p| p.is_file()));
387	            }
388	            clap::ValueHint::DirPath => {
389	                values.extend(complete_path(value_os, current_dir, &|p| p.is_dir()));
390	            }
391	            clap::ValueHint::ExecutablePath => {
392	                use is_executable::IsExecutable;
393	                values.extend(complete_path(value_os, current_dir, &|p| p.is_executable()));
394	            }
395	            clap::ValueHint::CommandName
396	            | clap::ValueHint::CommandString
397	            | clap::ValueHint::CommandWithArguments
398	            | clap::ValueHint::Username
399	            | clap::ValueHint::Hostname
400	            | clap::ValueHint::Url
401	            | clap::ValueHint::EmailAddress => {
402	                // No completion implementation
403	            }
404	            _ => {
405	                // Safe-ish fallback
406	                values.extend(complete_path(value_os, current_dir, &|_| true));
407	            }
408	        }
409	
410	        values.sort();
411	    }
412	
413	    if let Some(prefix) = prefix {
414	        values = values
415	            .into_iter()
416	            .map(|comp| comp.add_prefix(prefix))
417	            .collect();
418	    }
419	    values = values
420	        .into_iter()
421	        .map(|comp| {
422	            if comp.get_tag().is_some() {
423	                comp
424	            } else {
425	                comp.tag(Some(arg.to_string().into()))
426	            }
427	        })
428	        .collect();
429	
430	    debug!("complete_arg_value: values={values:?}");
431	    values
432	}
