434	fn rsplit_delimiter<'s, 'o>(
435	    value: Result<&'s str, &'o OsStr>,
436	    delimiter: Option<char>,
437	) -> Option<(Option<&'s str>, Result<&'s str, &'o OsStr>)> {
438	    let delimiter = delimiter?;
439	    let value = value.ok()?;
440	    let pos = value.rfind(delimiter)?;
441	    let (prefix, value) = value.split_at(pos + delimiter.len_utf8());
442	    Some((Some(prefix), Ok(value)))
443	}
