445	fn complete_value_candidates(
446	    value: &OsStr,
447	    completer: &dyn ValueCandidates,
448	) -> Vec<CompletionCandidate> {
449	    debug!("complete_value_candidates: value={value:?}");
450	
451	    let mut values = completer.candidates();
452	    values.retain(|comp| comp.get_value().starts_with(&value.to_string_lossy()));
453	    values
454	}
