466	fn complete_value_candidates_str(
467	    value: &str,
468	    completer: &dyn ValueCandidates,
469	) -> Vec<CompletionCandidate> {
470	    debug!("complete_value_candidates_str: value={value:?}");
471	
472	    complete_candidates_str(value, completer.candidates())
473	}
