501	/// Gets all the long options, their visible aliases and flags of a [`clap::Command`] with formatted `--` prefix.
502	/// Includes `help` and `version` depending on the [`clap::Command`] settings.
503	fn longs_and_visible_aliases(p: &clap::Command) -> Vec<CompletionCandidate> {
504	    debug!("longs: name={}", p.get_name());
505	
506	    p.get_arguments()
507	        .filter_map(|a| {
508	            a.get_long_and_visible_aliases().map(|longs| {
509	                longs
510	                    .into_iter()
511	                    .map(|s| populate_arg_candidate(CompletionCandidate::new(format!("--{s}")), a))
512	            })
513	        })
514	        .flatten()
515	        .collect()
516	}
517	
518	/// Gets all the long hidden aliases and flags of a [`clap::Command`].
519	fn hidden_longs_aliases(p: &clap::Command) -> Vec<CompletionCandidate> {
520	    debug!("longs: name={}", p.get_name());
521	
522	    p.get_arguments()
523	        .filter_map(|a| {
524	            a.get_aliases().map(|longs| {
525	                longs.into_iter().map(|s| {
526	                    populate_arg_candidate(CompletionCandidate::new(format!("--{s}")), a).hide(true)
527	                })
528	            })
529	        })
530	        .flatten()
531	        .collect()
532	}
