fn value_terminator_command() -> Command {
    Command::new("tool")
        .arg(
            clap::Arg::new("pair")
                .long("pair")
                .num_args(1..=3)
                .value_terminator(";")
                .add(ArgValueCandidates::new(|| {
                    ["pair-a", "pair-b", "pair-c"]
                        .into_iter()
                        .map(CompletionCandidate::new)
                        .collect::<Vec<_>>()
                })),
        )
        .arg(
            clap::Arg::new("tail").add(ArgValueCandidates::new(|| {
                ["tail-a", "tail-b", ";x"]
                    .into_iter()
                    .map(CompletionCandidate::new)
                    .collect::<Vec<_>>()
            })),
        )
        .arg(clap::Arg::new("verbose").long("verbose"))
}

#[test]
fn complete_value_terminator() {
    let mut cmd = value_terminator_command();
    // The first value of the option is completed from its own candidates.
    assert_data_eq!(
        complete!(cmd, "--pair [TAB]"),
        snapbox::str![[r#"
pair-a
pair-b
pair-c
"#]]
    );

    // The terminator only ends the value stream; it is not consumed as a value.
    assert_data_eq!(
        complete!(cmd, "--pair pair-a ; [TAB]"),
        snapbox::str![[r#"
tail-a
tail-b
;x
--pair
--verbose
--help	Print help
"#]]
    );

    // A token that merely ends with the terminator is not a terminator.
    assert_data_eq!(complete!(cmd, "--pair semi;[TAB]"), snapbox::str![""]);

    // After `--`, the terminator is still just a positional token.
    assert_data_eq!(
        complete!(cmd, "--pair pair-a ; -- ;[TAB]"),
        snapbox::str![";x"]
    );
}

#[test]
fn complete_value_terminator_without_value() {
    let mut cmd = value_terminator_command();
    // There is no token to complete, so no candidates are generated.
    let result = clap_complete::engine::complete(
        &mut cmd,
        vec!["tool".into(), "--pair".into()],
        2,
        None,
    );
    assert!(result.is_err());
}

#[test]
fn complete_value_terminator_candidate_metadata() {
    fn candidates(cmd: &mut Command, args: &[&str], arg_index: usize) -> Vec<CompletionCandidate> {
        clap_complete::engine::complete(
            cmd,
            args.iter().map(std::ffi::OsString::from).collect(),
            arg_index,
            None,
        )
        .unwrap()
    }

    let after_terminator = candidates(
        &mut value_terminator_command(),
        &["tool", "--pair", "pair-a", ";", ""],
        4,
    );
    let at_start = candidates(&mut value_terminator_command(), &["tool", ""], 1);

    assert_eq!(
        after_terminator
            .iter()
            .map(|c| c.get_value().to_owned())
            .collect::<Vec<_>>(),
        at_start
            .iter()
            .map(|c| c.get_value().to_owned())
            .collect::<Vec<_>>(),
    );
    for candidate in &after_terminator {
        let other = at_start
            .iter()
            .find(|other| other.get_value() == candidate.get_value())
            .unwrap();
        assert_eq!(candidate.get_help(), other.get_help());
        assert_eq!(candidate.get_id(), other.get_id());
        assert_eq!(candidate.get_tag(), other.get_tag());
        assert_eq!(candidate.get_display_order(), other.get_display_order());
        assert_eq!(candidate.is_hide_set(), other.is_hide_set());
    }
}

